async def notion_query_meeting_notes(caller: McpCaller, *, filter: dict | None = None) -> Any:
    """Query the current user's meeting notes data source.

    Applies a filter over meeting note properties. Title keyword searching is done via filter on property "title" (e.g. string_contains). Title keyword matching is case-insensitive; capitalization does not matter. Returns up to 50 rows of matching meeting notes.

    Prerequisites:
    1. Use the "search" tool to find people IDs if you need to filter by attendees


    Query building:
    - Ignore terms semantically related to meeting outputs (e.g. "summaries", "notes", "todos", "action items", "deliverables"). These signal the user wants outcomes from their meetings, not a title filter.
    - For example, "what are my meeting todos?" means filter meetings and find action items — do NOT add a title filter for "todos".
    - Only add a title filter when confident the user is targeting a specific meeting title (e.g. "standup", "sprint planning", "1:1 with Alice").
    - Generic date phrases like "recent meetings", "latest meetings", "meetings this week", or "yesterday's meetings" should be interpreted as date range filters — never as title filters.
    - If a filter returns no results, simplify to a single term. The system is lexical, so multi-word title filters may not match.
    - Unless a user explicitly asks about a meeting titled with another user's name, assume they're referring to attendees or creators. Only add a title filter with a person's name as a fallback if attendee filtering returns no results.


    Default behavior:
    - This tool by default returns meeting notes where the current user is an attendee or creator. There is no need to add a filter for the current user.


    Filterable properties:
    - "title" (text) — meeting title
    - "attendees" (person) — meeting attendees
    - "created_time" (date) — when the meeting note was created
    - "created_by" (person) — who created the meeting note
    - "last_edited_time" (date) — when the meeting note was last edited
    - "last_edited_by" (person) — who last edited the meeting note


    Combinator filters use "filters" (not "operands"): { "operator": "and" | "or", "filters": [ ... ] }

    Date filtering (recommended default: date_is_within):
    - Prefer "date_is_within" for relative windows like "past N days/weeks/months".
    - Relative (common): { type: "relative", value: "the_past_week" | "the_past_month" | "this_week" }
    - Relative (custom): { type: "relative", value: "custom", direction: "past" | "future", unit: "day" | "week" | "month" | "year", count: <number> }
    - Exact range: { type: "exact", value: { type: "daterange", start_date: "YYYY-MM-DD", end_date: "YYYY-MM-DD" } }
    - Single-date operators ("date_is", "date_is_before", "date_is_after", "date_is_on_or_before", "date_is_on_or_after"):
    - Exact: { type: "exact", value: { type: "date", start_date: "YYYY-MM-DD" } }
    - Relative shortcuts: today | tomorrow | yesterday | one_week_ago | one_week_from_now | one_month_ago | one_month_from_now


    Title keyword filtering (OR vs AND):
    - Use OR ("operator": "or") when unsure or for broad discovery.
    - Use AND ("operator": "and") when the user is specific and you want to narrow results.
    - Break multi-word phrases into individual terms and filter on each term separately.


    Example 1: Filter meetings from the past week (relative): { "filter": { "operator": "and", "filters": [ { "property": "created_time", "filter": { "operator": "date_is_within", "value": { "type": "relative", "value": "the_past_week" } } } ] } }

    Example 2: Filter meetings from the past 3 days (custom relative): { "filter": { "operator": "and", "filters": [ { "property": "created_time", "filter": { "operator": "date_is_within", "value": { "type": "relative", "value": "custom", "direction": "past", "unit": "day", "count": 3 } } } ] } }

    Example 3: Filter meetings by exact date range: { "filter": { "operator": "and", "filters": [ { "property": "created_time", "filter": { "operator": "date_is_within", "value": { "type": "exact", "value": { "type": "daterange", "start_date": "2025-01-01", "end_date": "2025-12-31" } } } } ] } }

    Example 4: Filter meetings created after a specific date: { "filter": { "operator": "and", "filters": [ { "property": "created_time", "filter": { "operator": "date_is_after", "value": { "type": "exact", "value": { "type": "date", "start_date": "2025-06-01" } } } } ] } }

    Example 5: Filter meetings by a specific attendee (use "search" tool first to get user ID): { "filter": { "operator": "and", "filters": [ { "property": "attendees", "filter": { "operator": "person_contains", "value": [ { "type": "exact", "value": { "table": "notion_user", "id": "a1b2c3d4-e5f6-7890-abcd-ef1234567890" } } ] } } ] } }

    Example 6: Combine attendees with date range: { "filter": { "operator": "and", "filters": [ { "property": "created_time", "filter": { "operator": "date_is_on_or_after", "value": { "type": "exact", "value": { "type": "date", "start_date": "2025-01-01" } } } }, { "property": "created_time", "filter": { "operator": "date_is_on_or_before", "value": { "type": "exact", "value": { "type": "date", "start_date": "2025-01-31" } } } }, { "property": "attendees", "filter": { "operator": "person_contains", "value": [ { "type": "exact", "value": { "table": "notion_user", "id": "a1b2c3d4-e5f6-7890-abcd-ef1234567890" } } ] } } ] } }

    Example 7: Filter meetings by title content: { "filter": { "operator": "and", "filters": [ { "property": "title", "filter": { "operator": "string_contains", "value": { "type": "exact", "value": "design review" } } } ] } }

    Example 8: Filter meetings matching any of several title terms (using "or"): { "filter": { "operator": "or", "filters": [ { "property": "title", "filter": { "operator": "string_contains", "value": { "type": "exact", "value": "standup" } } }, { "property": "title", "filter": { "operator": "string_contains", "value": { "type": "exact", "value": "sync" } } } ] } }

    Args:
        filter: Acceptable filter for querying current user's meeting notes data source.
    """
    args: dict[str, Any] = {}
    if filter is not None:
        args["filter"] = filter
