@overload
async def notion_search(caller: McpCaller, *, query: str, query_type: Literal['internal'], content_search_mode: Literal['workspace_search', 'ai_search'] | None = None, data_source_url: str | None = None, page_url: str | None = None, teamspace_id: str | None = None, filters: dict | None = None, page_size: int | None = None, max_highlight_length: int | None = None) -> list[SearchResultItem]: ...

@overload
async def notion_search(caller: McpCaller, *, query: str, query_type: Literal['user'], content_search_mode: Literal['workspace_search', 'ai_search'] | None = None, data_source_url: str | None = None, page_url: str | None = None, teamspace_id: str | None = None, filters: dict | None = None, page_size: int | None = None, max_highlight_length: int | None = None) -> list[SearchPersonItem]: ...

async def notion_search(caller: McpCaller, *, query: str, query_type: str, content_search_mode: Literal['workspace_search', 'ai_search'] | None = None, data_source_url: str | None = None, page_url: str | None = None, teamspace_id: str | None = None, filters: dict | None = None, page_size: int | None = None, max_highlight_length: int | None = None) -> list[SearchResultItem | SearchPersonItem]:
    """Search the user's Notion workspace and connected sources (Slack, Google Drive,
    GitHub, Jira, Teams, SharePoint, OneDrive, Linear) and return a ranked list
    of results to read. Two query types:
    - "internal" (default): content across Notion and connected sources.
    - "user": find people by name or email.


    When to use this vs. get-answer:
    - Use search when you want results to read, filter, cite, or fetch in full, or when you'll synthesize across sources yourself.
    - Use get-answer when you just want one synthesized answer and don't need the underlying pages. If its answer isn't good enough, come back to search for the full results.


    How to search well:
    - One question or topic per call. Make separate calls for separate needs.
    - If the question names a person, timeframe, teamspace, or database, pass the matching filter. Otherwise omit filters for the broadest recall.
    - Date filter values use the YYYY-MM-DD calendar-date format.
    - Keep responses small: set page_size (default 10, max 25) and max_highlight_length (default 200; 0 to omit) as low as you can.
    - After finding a Notion result, call fetch with its "id" for full contents.


    The backend is auto-selected: AI search when the user has Notion AI and connectors, otherwise faster workspace-only search. Use content_search_mode only when you specifically need one or the other.

    To search within a database: fetch the database first to get its data source URL (collection://...) from <data-source url="..."> tags, then pass that as data_source_url. For multi-source databases, match by view ID (?v=...) or search each source. Don't combine a database URL or ID with the collection:// prefix, and don't use a database URL as page_url.

    		<example description="Search with date range filter (only documents created in 2024)">
    		{
    			"query": "quarterly revenue report",
    			"query_type": "internal",
    			"filters": {
    				"created_date_range": {
    					"start_date": "2024-01-01",
    					"end_date": "2025-01-01"
    				}
    			}
    		}
    		</example>

    		<example description="Teamspace + creator filter">
    		{"query": "project updates", "query_type": "internal", "teamspace_id": "f336d0bc-b841-465b-8045-024475c079dd", "filters": {"created_by_user_ids": ["a1b2c3d4-e5f6-7890-abcd-ef1234567890"]}}
    		</example>

    		<example description="Database with date + creator filters">
    		{"query": "design review", "data_source_url": "collection://f336d0bc-b841-465b-8045-024475c079dd", "filters": {"created_date_range": {"start_date": "2024-10-01"}, "created_by_user_ids": ["a1b2c3d4-e5f6-7890-abcd-ef1234567890", "b2c3d4e5-f6a7-8901-bcde-f12345678901"]}}
    		</example>

    		<example description="User search">
    		{"query": "john@example.com", "query_type": "user"}
    		</example>

    Args:
        query: Semantic search query over your entire Notion workspace and connected sources (Slack, Google Drive, Github, Jira, Microsoft Teams, Sharepoint, OneDrive, or Linear). For best results, don't provide more than one question per tool call. Use a separate "search" tool call for each search you want to perform.

    Alternatively, the query can be a substring or keyword to find users by matching against their name or email address. For example: "john" or "john@example.com"
        query_type: Specify type of the query as either "internal" or "user". Always include this input if performing "user" search.. One of: 'internal', 'user'
        content_search_mode: Select search backend: "workspace_search" (faster, workspace-only) or "ai_search" (semantic, includes Slack/Linear/etc.). If omitted, uses AI search if available. Content searches only.. One of: 'workspace_search', 'ai_search'
        data_source_url: Optionally, provide the URL of a Data source to search. This will perform a semantic search over the pages in the Data Source. Note: must be a Data Source, not a Database. <data-source> tags are part of the Notion flavored Markdown format returned by tools like fetch. The full spec is available in the create-pages tool description.
        page_url: Optionally, provide the URL or ID of a page to search within. This will perform a semantic search over the content within and under the specified page. Accepts either a full page URL (e.g. https://notion.so/workspace/Page-Title-1234567890) or just the page ID (UUIDv4) with or without dashes.
        teamspace_id: Optionally, provide the ID of a teamspace to restrict search results to. This will perform a search over content within the specified teamspace only. Accepts the teamspace ID (UUIDv4) with or without dashes.
        filters: Optionally provide filters to apply to the search results. Only valid when query_type is 'internal'.
        page_size: Maximum number of results to return (default 10). Lower values reduce response size.
        max_highlight_length: Maximum character length for result highlights (default 200). Set to 0 to omit highlights entirely.
    """
    args: dict[str, Any] = {"query": query, "query_type": query_type}
    if content_search_mode is not None:
        args["content_search_mode"] = content_search_mode
    if data_source_url is not None:
        args["data_source_url"] = data_source_url
    if page_url is not None:
        args["page_url"] = page_url
    if teamspace_id is not None:
        args["teamspace_id"] = teamspace_id
    if filters is not None:
        args["filters"] = filters
    if page_size is not None:
        args["page_size"] = page_size
    if max_highlight_length is not None:
        args["max_highlight_length"] = max_highlight_length
    result = await caller.call(SERVER, "notion-search", args)
    return cast("list[SearchResultItem | SearchPersonItem]", _dig_list(result, ('results', )))

